#!/bin/bash
# Rewrites Casks/macclean.rb with a pinned version and checksum.
# Usage: scripts/update_cask.sh <version> <path/to/MacClean.zip>
#        scripts/update_cask.sh 0.2.0 build/MacClean.zip
set -euo pipefail

cd "$(dirname "$0")/.."

VERSION="${1:?version, for example 0.2.0}"
ZIP="${2:?path to MacClean.zip}"
SHA="$(shasum -a 256 "$ZIP" | cut -d' ' -f1)"

cat > Casks/macclean.rb <<CASK
# Homebrew cask for MacClean.
#
#   brew tap temidayomichael/macclean https://github.com/Temidayomichael/macclean
#   brew install --cask macclean
#
# Generated by scripts/update_cask.sh; do not edit the version or sha256 by hand.
cask "macclean" do
  version "$VERSION"
  sha256 "$SHA"

  url "https://github.com/Temidayomichael/macclean/releases/download/v#{version}/MacClean.zip"
  name "MacClean"
  desc "Uninstall apps completely and clean caches, logs and old installers"
  homepage "https://github.com/Temidayomichael/macclean"

  livecheck do
    url :url
    strategy :github_latest
  end

  depends_on macos: ">= :ventura"

  app "MacClean.app"

  zap trash: [
    "~/Library/Preferences/io.github.temidayomichael.macclean.plist",
    "~/Library/Saved Application State/io.github.temidayomichael.macclean.savedState",
  ]
end
CASK

echo "Casks/macclean.rb now points at v$VERSION ($SHA)"
